#!/usr/bin/env node
// Tests for src/lemonade_art.js (generated by tools/make_art.py) and how the
// door uses it. Plain node, no dependencies.
"use strict";
const assert = require("assert");
const fs = require("fs");
const path = require("path");

const ART_FILE = path.join(__dirname, "..", "src", "lemonade_art.js");
const DOOR_FILE = path.join(__dirname, "..", "src", "lemonade.js");
const ART = require(ART_FILE);
const door = fs.readFileSync(DOOR_FILE, "latin1");
let pass = 0, fail = 0;
function test(name, fn) {
  try { fn(); pass++; console.log("ok   " + name); }
  catch (e) { fail++; console.log("FAIL " + name + "\n     " + (e && e.message)); }
}
const visible = (s) => s.replace(/\x01./g, "").length;

test("art module is ES5 (Synchronet's SpiderMonkey)", () => {
  const src = fs.readFileSync(ART_FILE, "latin1").replace(/\/\/.*$/gm, "");
  assert.ok(!/\b(let|const)\s/.test(src) && !/=>/.test(src) && !/`/.test(src));
});
test("every piece: lines match height, widths match and fit 79 columns", () => {
  for (const [name, p] of Object.entries(ART)) {
    assert.strictEqual(p.lines.length, p.height, name + " height");
    const w = Math.max(...p.lines.map(visible));
    assert.strictEqual(w, p.width, name + " width");
    assert.ok(p.width <= 79, name + " too wide");
    assert.ok(p.height <= 18, name + " too tall for a 25-row screen with text");
  }
});
test("only Ctrl-A attribute codes the art encoder emits (n h colours 1-7)", () => {
  for (const [name, p] of Object.entries(ART))
    for (const line of p.lines) {
      for (const m of line.matchAll(/\x01(.)/g))
        assert.ok(/[nhkrgybmcw1-7]/.test(m[1]), name + ": \\x01" + m[1]);
      assert.ok(line.endsWith("\x01n"), name + ": row must end by resetting colour");
    }
});
test("art uses only block characters and spaces (plus letters in none)", () => {
  for (const [name, p] of Object.entries(ART))
    for (const line of p.lines)
      for (const ch of line.replace(/\x01./g, ""))
        assert.ok(" \xdb\xdc\xdf".includes(ch), name + ": " + ch.charCodeAt(0).toString(16));
});
test("every piece the door draws exists", () => {
  const named = [...door.matchAll(/drawArt\("([a-z_]+)"/g)].map((m) => m[1]);
  for (const n of ["weather_sun", "weather_partly", "weather_rain", "day_rain", "day_sales",
                   "day_loss", "season_bust", "season_end"])
    assert.ok(door.includes('"' + n + '"'), "door names " + n);
  for (const n of named.concat(["news_sugar", "news_lemons", "news_cups",
      "weather_sun", "weather_partly", "weather_rain", "day_rain", "day_sales", "day_loss",
      "season_bust", "season_end"]))
    assert.ok(ART[n], "missing art: " + n);
});
test("news art exists for every engine news event", () => {
  const engine = fs.readFileSync(path.join(__dirname, "..", "src", "lemonade_engine.js"), "latin1");
  const events = [...engine.matchAll(/event: "([a-z]+)"/g)].map((m) => m[1]);
  assert.deepStrictEqual([...new Set(events)].sort(), ["cups", "lemons", "sugar"]);
  for (const e of events) assert.ok(ART["news_" + e], "news_" + e);
});
test("door skips art on non-ANSI terminals", () => {
  assert.ok(/function drawArt[\s\S]*?!ansi\(\)/.test(door));
});

console.log(`${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
